def ok(response):
    if response.status_code not in {200, 201}:
        pytest.fail(f"goal harness HTTP failure: {response.status_code}: {response.text}")
    return response.json()


def field(value, region, label=None, state=None):
    return {"state": state or ("observed" if value is not None else "not_applicable"),
            "raw_value": value, "source_label": label,
            "evidence": [{"page_number": 1, "region_reference": region}] if value is not None else [],
            "alternative_readings": []}


def product_row(index, *, code=None, description=None, quantity=None, kind="product"):
    region = f"line-{index}"
    return {"row_id": region, "row_kind": kind,
            "evidence": [{"page_number": 1, "region_reference": region}],
            "identifiers": [{**field(code, region, "Code"), "source_role": "vendor_sku"}] if code else [],
            "description": field(description, region, "Description"),
            "quantity": field(quantity, region, "Quantity"), "unit": field("EA" if quantity else None, region),
            "unit_price": field(None, region), "line_total": field(None, region),
            "uncertainty": "Needs human classification" if kind == "unknown" else None}


def payload(rows):
    return {"contract_name": "ProductDocument", "schema_version": "1.1",
            "document_type": "purchase_order", "document_type_reason": None,
            "document_number": field("GOAL-PO-001", "header"),
            "vendor_name": field("Synthetic goal vendor", "header"), "currency": field(None, "header"),
            "pages": [{"page_number": 1, "state": "complete", "uncertainty": None, "regions": [
                {"region_reference": "header", "bbox": {"x0": .04, "y0": .04, "x1": .96, "y1": .15}},
                *[{"region_reference": row["row_id"], "bbox": {"x0": .04, "y0": .18 + i * .075,
                   "x1": .96, "y1": .245 + i * .075}} for i, row in enumerate(rows)]]}],
            "rows": rows, "warnings": []}


def source_bytes(rows, media_type="application/pdf", *, code_column=True):
    """Generate only the supplied fictional printed rows; no provider inference."""
    lines = [(0.09, "SYNTHETIC PURCHASE ORDER GOAL-PO-001")]
    for i, row in enumerate(rows):
        code = row["identifiers"][0]["raw_value"] if row["identifiers"] else ""
        text = " | ".join(str(value or "") for value in (
            ([code] if code_column else []) + [row["description"]["raw_value"], row["quantity"]["raw_value"]]))
        lines.append((.22 + i * .075, text))
    output = BytesIO()
    if media_type == "application/pdf":
        canvas = Canvas(output, pagesize=(900, 1100), invariant=1)
        canvas.setFont("Helvetica", 12)
        for y, text in lines:
            canvas.drawString(45, 1100 * (1 - y), text)
        canvas.showPage()
        canvas.save()
    else:
        image = Image.new("RGB", (1400, 1800), "white")
        draw = ImageDraw.Draw(image)
        font = ImageFont.load_default(size=22)
        for y, text in lines:
            draw.text((70, 1800 * y), text, fill="black", font=font)
        image.save(output, format="PNG" if media_type == "image/png" else "JPEG")
    return output.getvalue()


def process(desk, rows, *, observed=None, media_type="application/pdf", code_column=True, use_default_pool=False):
    data = source_bytes(rows, media_type, code_column=code_column)
    desk.provider.set_payload(payload(deepcopy(rows) if observed is None else observed))
    source = ok(desk.client.post("/documents", headers={"Idempotency-Key": uuid4().hex},
        data={} if use_default_pool else {"vendor_id": desk.vendor["id"]}, files={"file": ("synthetic", data, media_type)}))
    run = ok(desk.client.post(f"/documents/{source['id']}/runs", headers={"Idempotency-Key": uuid4().hex},
                             json={"provider": "synthetic"}))
    run = ok(desk.client.post(f"/runs/{run['id']}/process"))
    if not desk.provider.calls or desk.provider.calls[-1] != (data, media_type, 1):
        pytest.fail("goal harness did not call the fixed provider with the generated source")
    result = ok(desk.client.get(f"/runs/{run['id']}/result"))
    suggestions = ok(desk.client.get(f"/runs/{run['id']}/suggestions"))["suggestions"]
    summary = ok(desk.client.get(f"/runs/{run['id']}/summary"))
    return SimpleNamespace(run=run, source=source, result=result, suggestions=suggestions, summary=summary)


def review_body(row, action, **kwargs):
    return {"row_id": row["row_id"], "action": action, "reviewer": "Fictional goal reviewer",
            "reason": "Checked generated synthetic evidence", "evidence_reference": row["evidence"], **kwargs}
